@page "/"
@using RecipeShare.Models

<PageTitle>RecipeShare - Home</PageTitle>

<div class="container">
    <div class="text-center my-5">
        <h1 class="display-4">🍳 RecipeShare</h1>
        <p class="lead">Discover and share delicious recipes from around the world</p>
    </div>

    <h2 class="mb-4">Browse by Category</h2>
    <div class="row">
        @foreach (var category in RecipeStore.Categories)
        {
            <div class="col-md-4 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body text-center">
                        <h3 class="card-title">@GetEmoji(category) @category</h3>
                        <p class="card-text text-muted">
                            @RecipeStore.ByCategory(category).Count() recipes
                        </p>
                        <a href="/category/@category" class="btn btn-outline-primary">Browse Recipes</a>
                    </div>
                </div>
            </div>
        }
    </div>

    <div class="text-center mt-4">
        <a href="/submit" class="btn btn-success btn-lg">📝 Submit a Recipe</a>
    </div>
</div>

@code {
    private static string GetEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Thai" => "🍜",
        _ => "🍽️"
    };
}

toolArgs.file_text:
@page "/recipe/{Id:int}"
@using RecipeShare.Models

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/category/@recipe.Category">@recipe.Category</a></li>
                <li class="breadcrumb-item active">@recipe.Title</li>
            }
        </ol>
    </nav>

    @if (recipe is null)
    {
        <div class="alert alert-danger">Recipe not found.</div>
    }
    else
    {
        <h1>@recipe.Title</h1>
        <span class="badge bg-secondary mb-3">@recipe.Category</span>

        <div class="my-3">
            <StarRating RecipeId="@recipe.Id" CurrentRating="@recipe.AverageRating" RatingCount="@recipe.RatingCount" />
        </div>

        <div class="row mt-4">
            <div class="col-md-4">
                <div class="card">
                    <div class="card-header"><h5 class="mb-0">🥘 Ingredients</h5></div>
                    <ul class="list-group list-group-flush">
                        @foreach (var ingredient in recipe.Ingredients)
                        {
                            <li class="list-group-item">@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
            <div class="col-md-8">
                <div class="card">
                    <div class="card-header"><h5 class="mb-0">📋 Steps</h5></div>
                    <div class="card-body">
                        <ol class="mb-0">
                            @foreach (var step in recipe.Steps)
                            {
                                <li class="mb-2">@step</li>
                            }
                        </ol>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeStore.GetById(Id);
    }
}

@using RecipeShare.Models
@rendermode InteractiveServer

<div class="d-inline-block">
    <span class="fs-4">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span role="button" class="@(star <= (hoveredStar > 0 ? hoveredStar : selectedStar) ? "text-warning" : "text-muted")"
                  style="cursor: pointer;"
                  @onmouseover="() => hoveredStar = star"
                  @onmouseout="() => hoveredStar = 0"
                  @onclick="() => Rate(star)">★</span>
        }
    </span>
    <span class="ms-2 text-muted">
        @if (selectedStar > 0)
        {
            <span class="text-success">You rated @selectedStar/5! </span>
        }
        (@CurrentRating / 5, @RatingCount ratings)
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int hoveredStar;
    private int selectedStar;

    private void Rate(int stars)
    {
        selectedStar = stars;
        RecipeStore.AddRating(RecipeId, stars);
        var recipe = RecipeStore.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

